using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Theory]
    // AC-1 — Bronze basket
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Returning_customer_is_charged_the_subtotal_less_the_reduction_for_their_tier(
        LoyaltyTier tier, int subtotalCents, int expectedChargedCents)
    {
        var pricing = new CalculateLoyaltyDiscount();

        var quote = pricing.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
EOF
cat > .copilot-tracking/skraft-plans/pricing/features/pricing-loyalty-discount.feature <<'EOF'
Feature: Loyalty tier discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED      : AC-1, AC-2, AC-3 (tier reductions on a 10000-cent subtotal).
  # SETTLED VALUE, OPEN PRINCIPLE : AC-4 (see @needs-clarification note on it).
  # NOT DECIDED  : Platinum tier - no reduction agreed, NO scenario exists on purpose.
  #                Do not infer a value; it must come from DISCUSS.

  @loyalty-discount @happy-path @smoke
  Scenario: Bronze customer is charged the reduced basket total
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @loyalty-discount @happy-path
  Scenario: Silver customer is charged the reduced basket total
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @loyalty-discount @happy-path
  Scenario: Gold customer is charged the reduced basket total
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  # AC-4 title says the reduction lands "in the customer's favour", yet 7 cents charged
  # means no reduction was given on a 7-cent basket. Value copied verbatim; the stated
  # rounding principle is ambiguous and is escalated to DISCUSS. The rounding rule for
  # other subtotals is NOT decided.
  @loyalty-discount @edge-case @needs-clarification
  Scenario: Bronze customer with a very small basket is charged a whole number of cents
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
(dotnet test tests/CheckoutPricing.UnitTest --no-restore --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > /tmp/red.out 2>&1; echo $? > /tmp/red.exit); tail -20 /tmp/red.out; cat /tmp/red.exit

